\title{A Pell Obstruction to a Proposed Family of Optimal Equidistant Codes for $n \equiv 2 \pmod 4$}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
An optimal equidistant binary code of length $n \equiv 2 \pmod 4$ is equivalent to a symmetric $2\text{-}(v,k,\lambda)$ block design. A recent speculative proposal suggested that a new, uncharted infinite family of such optimal codes exists, indexed by a nonnegative integer $u$, with parameters $v = 12u^2 + 8u + 2$, $k = 6u^2 + u$, and $\lambda = k(k-1)/(v-1)$. We carry out an adversarial analysis. First, the quotient defining $\lambda$ collapses to the polynomial $\lambda = 3u^2 - u$, so the design order is $k - \lambda = u(3u+2)$. Second, $v \equiv 2 \pmod 4$ is always even, so the Bruck--Ryser--Chowla theorem forces the order to be a perfect square. Third---the central observation---the identity $(3u+1)^2 = 3\,u(3u+2) + 1$ converts the perfect-square condition into the Pell equation $x^2 - 3y^2 = 1$ with $x = 3u+1$. Hence the admissible parameters form a sparse Pell orbit $u = 0, 2, 32, 450, \dots$, not a dense set. In particular the existence claim fails at $u = 1$, where the order would be $5$, ruling out the symmetric $2\text{-}(22,7,2)$ design. We give the correct Diophantine characterization, exhibit explicit admissible members, and prove that a Pell step yields infinitely many admissible parameters.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Equidistant codes and symmetric designs}
A binary code $C \subseteq \{0,1\}^n$ is \emph{equidistant} if every pair of distinct codewords lies at a fixed Hamming distance $d$. Write $\mathrm{EC}(n,d,m)$ for such a code with $m$ codewords, and call it \emph{optimal} when $m$ is maximal for the given $(n,d)$. A classical dictionary connects optimal equidistant codes to combinatorial designs: an optimal $\mathrm{EC}\!\left(n,\tfrac{n-2}{2},m^*\right)$ with $n \equiv 2 \pmod 4$ is equivalent to a symmetric balanced incomplete block design.

\subsection{Symmetric designs}
A \emph{$2\text{-}(v,k,\lambda)$ design} consists of $v$ points and a collection of $k$-element blocks such that every pair of points lies in exactly $\lambda$ blocks. It is \emph{symmetric} when the number of blocks equals $v$, in which case
\begin{equation}\label{eq:fundamental}
\lambda(v-1) = k(k-1).
\end{equation}
The \emph{order} is $k - \lambda$. The Bruck--Ryser--Chowla (BRC) theorem states: if $v$ is even, then $k - \lambda$ must be a perfect square.

\subsection{The proposal}
The proposal considered, for $u \in \mathbb{N}$,
\begin{equation}\label{eq:family}
v = 12u^2 + 8u + 2, \qquad k = 6u^2 + u, \qquad \lambda = \frac{k(k-1)}{v-1},
\end{equation}
claiming each triple is realized by an optimal equidistant code (a symmetric design) and that the family is new. We show the existence claim fails and give the precise Diophantine truth.

\section{Definitions}
\begin{definition}
For $u \in \mathbb{Z}$ set $v(u) = 12u^2 + 8u + 2$, $k(u) = 6u^2 + u$, $\lambda(u) = 3u^2 - u$. We call $u$ \emph{admissible} if the order $u(3u+2)$ is a perfect square. A \emph{Pell solution} is $(x,y) \in \mathbb{Z}^2$ with $x^2 - 3y^2 = 1$.
\end{definition}

\section{The index collapses to a polynomial}

\begin{theorem}[$\lambda$ collapse]\label{thm:collapse}
For every integer $u$, $\ \lambda(u)\,(v(u)-1) = k(u)\,(k(u)-1)$.
\end{theorem}
\begin{proof}
Both sides expand to $36u^4 + 12u^3 - 5u^2 - u$.
\end{proof}

\begin{theorem}[denominator factorization]\label{thm:den}
$v(u) - 1 = (2u+1)(6u+1)$.
\end{theorem}
\begin{proof}
$(2u+1)(6u+1) = 12u^2 + 8u + 1 = v(u) - 1$.
\end{proof}

\begin{theorem}[numerator factorization]\label{thm:num}
$k(u)\,(k(u)-1) = u(6u+1)(2u+1)(3u-1)$.
\end{theorem}
\begin{proof}
$k(u) = u(6u+1)$ and $k(u)-1 = (2u+1)(3u-1)$; multiply.
\end{proof}

Comparing Theorems~\ref{thm:den} and \ref{thm:num}, the factors $(2u+1)$ and $(6u+1)$ cancel, giving $\lambda(u) = u(3u-1) = 3u^2 - u$; thus $v-1 \mid k(k-1)$ exactly for all $u$.

\begin{theorem}[order formula]\label{thm:order}
$k(u) - \lambda(u) = u(3u+2)$.
\end{theorem}
\begin{proof}
$(6u^2 + u) - (3u^2 - u) = 3u^2 + 2u = u(3u+2)$.
\end{proof}

\section{The point count is even}
\begin{theorem}[parity]\label{thm:parity}
$v(u) \equiv 2 \pmod 4$ for every $u$; in particular $v(u)$ is even.
\end{theorem}
\begin{proof}
$v(u) = 4(3u^2 + 2u) + 2$.
\end{proof}
Hence BRC applies to every member and requires $u(3u+2)$ to be a perfect square.

\section{The Pell bridge}
\begin{theorem}[Pell identity]\label{thm:pellid}
$(3u+1)^2 = 3\,\big(u(3u+2)\big) + 1$ for every integer $u$.
\end{theorem}
\begin{proof}
$(3u+1)^2 = 9u^2 + 6u + 1 = 3(3u^2 + 2u) + 1$.
\end{proof}

\begin{theorem}[square $\Leftrightarrow$ Pell]\label{thm:iff}
The order $u(3u+2)$ is a perfect square if and only if there is an integer $m$ with $(3u+1)^2 - 3m^2 = 1$.
\end{theorem}
\begin{proof}
If $u(3u+2) = m^2$, then by Theorem~\ref{thm:pellid} $(3u+1)^2 - 3m^2 = 1$. Conversely, if $(3u+1)^2 - 3m^2 = 1$, then $3\,u(3u+2) + 1 = 3m^2 + 1$, so $u(3u+2) = m^2$.
\end{proof}

\section{The obstruction and explicit members}
\begin{theorem}[the $u=1$ obstruction]\label{thm:obstruction}
The order $5$ at $u = 1$ is not a perfect square: $1\cdot(3\cdot 1 + 2) = 5 \ne m^2$ for all $m \in \mathbb{Z}$.
\end{theorem}
\begin{proof}
If $m^2 = 5$ then $|m| \le 2$, but $m^2 \in \{0,1,4\}$ for $|m| \le 2$.
\end{proof}

\begin{corollary}
$(v(1),k(1),\lambda(1)) = (22,7,2)$. Since $v = 22$ is even and the order $5$ is not a square, no symmetric $2\text{-}(22,7,2)$ design---hence no optimal equidistant code with these parameters---exists.
\end{corollary}

\begin{theorem}[$u=2$ member]\label{thm:u2}
$(v(2),k(2),\lambda(2)) = (66,26,10)$; the order is $16 = 4^2$ and $(7,4)$ solves $x^2 - 3y^2 = 1$.
\end{theorem}

\begin{theorem}[$u=32$ member]\label{thm:u32}
The order is $32\cdot 98 = 3136 = 56^2$ and $(97,56)$ solves $x^2 - 3y^2 = 1$.
\end{theorem}

\section{Infinitely many admissible parameters}
\begin{theorem}[Pell step]\label{thm:step}
If $x^2 - 3y^2 = 1$, then $(2x+3y)^2 - 3(x+2y)^2 = 1$.
\end{theorem}
\begin{proof}
$(2x+3y)^2 - 3(x+2y)^2 = x^2 - 3y^2 = 1$ after expansion.
\end{proof}

\begin{theorem}[admissibility step]\label{thm:adstep}
If $u \ge 0$, $m \ge 1$, and $(3u+1)^2 - 3m^2 = 1$, then with $u' = 7u+4m+2$ and $m' = 12u+7m+4$ we have $(3u'+1)^2 - 3(m')^2 = 1$ and $u' > u$.
\end{theorem}
\begin{proof}
Direct expansion using the hypothesis; $u' > u$ is immediate.
\end{proof}

\begin{theorem}[infinitude]\label{thm:inf}
For every $N$ there is an admissible $u > N$ with $(3u+1)^2 - 3m^2 = 1$ for some $m \ge 1$. The admissible indices are $0, 2, 32, 450, 6272, \dots$.
\end{theorem}
\begin{proof}
From the base $(u,m) = (2,4)$, iterate Theorem~\ref{thm:adstep}; each step increases $u$ by at least $1$.
\end{proof}

\begin{remark}
The admissible indices satisfy $u_{n+1} = 14u_n - u_{n-1} + 4$ ($u_0 = 0$, $u_1 = 2$), and the order roots satisfy $m_{n+1} = 14 m_n - m_{n-1}$ ($m_0 = 0$, $m_1 = 4$), both inherited from the Pell companion recurrence.
\end{remark}

\section{Discussion}
The existence claim is false at $u = 1$, but the failure exposes structure: the substitution $x = 3u+1$ converts ``order is a square'' into the Pell equation $x^2 - 3y^2 = 1$, whose solutions are sparse. The correct statement is a Diophantine characterization---admissibility holds precisely along the Pell orbit $0, 2, 32, 450, \dots$. BRC-admissibility is necessary but not sufficient: whether the surviving members host genuine designs requires finer invariants.

