"""Parameter functions and the lambda-collapse verification."""
from math import isqrt

def v(u: int) -> int:
    return 12 * u ** 2 + 8 * u + 2

def k(u: int) -> int:
    return 6 * u ** 2 + u

def lam(u: int) -> int:
    return 3 * u ** 2 - u

def order(u: int) -> int:
    return u * (3 * u + 2)

def lambda_collapse_report(u_max: int = 12) -> None:
    """Show that k(k-1)/(v-1) is integral and equals 3u^2 - u."""
    print(f"{'u':>3} {'v-1':>8} {'k(k-1)':>12} {'quotient':>9} {'3u^2-u':>8}")
    for u in range(u_max + 1):
        num, den = k(u) * (k(u) - 1), v(u) - 1
        assert num % den == 0 and num // den == lam(u)
        print(f"{u:>3} {den:>8} {num:>12} {num // den:>9} {lam(u):>8}")

if __name__ == "__main__":
    lambda_collapse_report()

"""Enumerate admissible u (order a perfect square) two ways and cross-check."""
from math import isqrt

def order(u: int) -> int:
    return u * (3 * u + 2)

def is_square(n: int) -> bool:
    if n < 0:
        return False
    r = isqrt(n)
    return r * r == n

def brute_force(u_max: int) -> list[int]:
    return [u for u in range(u_max + 1) if is_square(order(u))]

def pell_orbit(u_max: int) -> list[int]:
    orbit = [0]
    u, m = 2, 4
    while u <= u_max:
        orbit.append(u)
        u, m = 7 * u + 4 * m + 2, 12 * u + 7 * m + 4
    return orbit

if __name__ == "__main__":
    U = 2000
    bf = brute_force(U)
    pl = [u for u in pell_orbit(U) if u <= U]
    print("brute force:", bf)
    print("pell orbit :", pl)
    assert bf == pl
    print("MATCH: admissibility is exactly the Pell orbit, not all of N.")

